const fmt = $json.output || {};
const body = ($('Webhook').first().json.body) || {};
const user = body.user || {};
const ctx = body.context || {};
const category = fmt.category || 'unknown';
const actions = Array.isArray(fmt.actionsTaken) ? fmt.actionsTaken : [];
const emojiMap = { bug: '🐛', 'feature-request': '💡', question: '❓', urgent: '🚨' };
const emoji = emojiMap[category] || '🏷️';
const actionLine = actions.length ? actions.map(a => a.type + ': ' + (a.ref || 'n/a')).join(', ') : 'none (answered from knowledge base)';
const rawMsg = (body.message || '').replace(/\s+/g, ' ').trim();
const msgTrunc = rawMsg.length > 200 ? rawMsg.slice(0, 200) + '…' : rawMsg;
const when = body.timestamp || new Date().toISOString();
const wsSuffix = ctx.workspaceId ? ' (ws ' + ctx.workspaceId + ')' : '';
const urgentPrefix = category === 'urgent' ? '<!here> ' : '';
const lines = [urgentPrefix + emoji + ' *' + category.toUpperCase() + '* support request', '*Ref:* exec-' + $execution.id, '*User:* ' + (user.email || 'unknown') + wsSuffix, '*Page:* ' + (ctx.pagePath || 'n/a'), '*Asked:* "' + msgTrunc + '"', '*Action:* ' + actionLine, '*When:* ' + when];
const auditText = lines.join('\n');
return [{ json: { output: fmt, auditText } }];
